def recolor(grid, mapping):
    """The grid with each cell value v replaced by mapping[v] (v kept if absent)."""
    return [[mapping.get(v, v) for v in row] for row in grid]

def promote_min_to_max_then_zero(grid):
    """With values sorted, the largest color becomes 0 and the smallest becomes the largest."""
    vals = sorted({v for row in grid for v in row})
    m = {vals[-1]: 0}
    if len(vals) > 1:
        m[vals[0]] = vals[-1]
    return [[m.get(v, v) for v in row] for row in grid]
